#include <iostream>
#include <vector>
using namespace std;

int main() {
    vector<long long> v(4);
    long long total = 0;

    for (long long& x : v) {
        cin >> x;
        total += x;
    }

    for (int mask = 1; mask < 15; ++mask) {
        long long sum = 0;
        for (int i = 0; i < 4; ++i) {
            if (mask & (1 << i)) sum += v[i];
        }
        if (sum * 2 == total) {
            cout << "YES\n";
            return 0;
        }
    }

    cout << "NO\n";
    return 0;
}

